-- Torneo actual: ajusta el id/nombre si vas a lanzar en otro torneo.
  on conflict (id) do nothing;

on conflict (short) do update set name = excluded.name, nickname = excluded.nickname, icon = excluded.icon;

on conflict (id) do update set name = excluded.name, pos = excluded.pos, club_short = excluded.club_short, price = excluded.price,
  form = excluded.form, projection = excluded.projection, value_score = excluded.value_score, role = excluded.role, availability = excluded.availability;

on conflict (id) do update set name = excluded.name, club_short = excluded.club_short, nat = excluded.nat, price = excluded.price,
  profile = excluded.profile, formation = excluded.formation;

